const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const BASE_PREMIUM_PER_ITEM = 100;

const insuredItemsOf = (step: Step): Item[] => (step.op === "quote" ? step.items : []);

const quoteFor = (items: Item[]): Result => {
  const policyBase = items.length * BASE_PREMIUM_PER_ITEM;
  return {
    premium: policyBase * (1 + FIRST_INSURANCE_SURCHARGE_RATE) + PROCESSING_FEE,
  };
};

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map((step) => quoteFor(insuredItemsOf(step))),
});

return {
  premium: policyBase + policyBase * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE,
};

